mapper.select:
SELECT id, point_name AS pointName, description, difficulty, order_index AS orderIndex, course_id AS courseId FROM knowledge_points WHERE course_id IN
#{courseId}
ORDER BY course_id, order_index

SELECT km.knowledge_point_id,
       COUNT(DISTINCT km.student_id) AS total_students
FROM knowledge_mastery km
JOIN knowledge_points kp ON km.knowledge_point_id = kp.id
JOIN class_students cs ON km.student_id = cs.student_id
WHERE 1=1
AND cs.class_id = #{classId}
AND km.student_id = #{studentId}
AND km.knowledge_point_id = #{knowledgePointId}
GROUP BY km.knowledge_point_id

SELECT DISTINCT km.student_id
FROM knowledge_mastery km
JOIN knowledge_points kp ON km.knowledge_point_id = kp.id
JOIN class_students cs ON km.student_id = cs.student_id
WHERE km.mastery_level IN ('一般', '较差')
AND kp.course_id = #{courseId}
AND cs.class_id = #{classId}
AND km.student_id = #{studentId}
AND km.knowledge_point_id = #{knowledgePointId}

SELECT DISTINCT cs.student_id
FROM class_students cs
WHERE cs.class_id IN (
    SELECT cc.id FROM course_classes cc WHERE cc.course_id = #{courseId}
    UNION
    SELECT cc_c.class_id FROM class_courses cc_c WHERE cc_c.course_id = #{courseId}
)

SELECT DISTINCT cs.student_id
FROM class_students cs
WHERE cs.class_id IN (
    SELECT cc.id FROM course_classes cc WHERE cc.teacher_id = #{teacherId}
    UNION
    SELECT cc_c.class_id FROM class_courses cc_c WHERE cc_c.teacher_id = #{teacherId}
)

SELECT km.student_id, km.knowledge_point_id, km.mastery_level, CASE km.mastery_level WHEN '优秀' THEN 95 WHEN '良好' THEN 80 WHEN '一般' THEN 65 WHEN '较差' THEN 40 ELSE 0 END AS mastery_rate FROM knowledge_mastery km WHERE km.knowledge_point_id IN
#{kpId}
AND km.student_id IN
#{studentId}
